local x=np.astype(np.arange(0,"int64"):reshape({0}),"float64")
local before=x:tolist()
local y=r:permuted(x,nil,x)
deep(y.dtype,"float64","42/(0,)/float64/plain/None/out_same dtype")
deep(y:tolist(),{},"42/(0,)/float64/plain/None/out_same values")
deep(x:tolist(),{},"42/(0,)/float64/plain/None/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"c621fbcd16d92688","42/(0,)/float64/plain/None/out_same pcg")
cases=cases+1; end
