local x=np.astype(np.arange(6,"int64"):reshape({2,3}),"bool")
local before=x:tolist()
local y=r:permuted(x,1,x)
deep(y.dtype,"bool","42/(2, 3)/bool/plain/0/out_same dtype")
deep(y:tolist(),{{true,true,true},{false,true,true}},"42/(2, 3)/bool/plain/0/out_same values")
deep(x:tolist(),{{true,true,true},{false,true,true}},"42/(2, 3)/bool/plain/0/out_same source")
assert(rawequal(y,x),"out must return identical ndarray")
deep(r:raw_hex(),"dbcd12c26eda1624","42/(2, 3)/bool/plain/0/out_same pcg")
cases=cases+1; end
